1	/* BH1750 ambient light sensor driver (see light_sensor.h).
2	 *
3	 * Purpose: speaks the BH1750 protocol over the gt_i2c_ops seam: power-on and
4	 * mode select at open, a 2-byte measurement read, and the read retry policy
5	 * from DESIGN.md's failure-mode table ("Retry 3x at 10 ms, then skip").
6	 * It makes no system calls itself; all bus traffic and waits go through
7	 * bus.ops, so tests can run every path against a fake bus.
8	 *
9	 * Device model: after POWER_ON + CONT_HRES the chip measures continuously
10	 * (high-res, 1 lx/count, <= 180 ms per conversion) and each 2-byte read
11	 * returns the latest result, high byte first. Lux = count / 1.2. The driver
12	 * returns the raw count; conversion happens downstream.
13	 *
14	 * Not here: offline/online tracking after repeated failures. That belongs to
15	 * the light_sensor process, which sees the run of consecutive errors. */
16	#include "light_sensor.h"
17	
18	#include <stdlib.h>
19	
20	struct gt_light_sensor {
21	    gt_i2c_bus bus;
22	};
23	
24	/* Send a one-byte BH1750 opcode. */
25	static gt_status send_cmd(gt_light_sensor *s, uint8_t op)
26	{
27	    return s->bus.ops->write(s->bus.ctx, &op, 1);
28	}
29	
30	/* Open the BH1750 on the Linux bus `i2c_dev` at GT_LIGHT_I2C_ADDR.
31	 * Returns NULL if the bus cannot be opened or the device does not respond. */
32	gt_light_sensor *gt_light_open(const char *i2c_dev)
33	{
34	    gt_i2c_bus bus;
35	    if (gt_i2c_linux_open(i2c_dev, GT_LIGHT_I2C_ADDR, &bus) != GT_OK) {
36	        return NULL;
37	    }
38	    return gt_light_open_bus(bus);
39	}
40	
41	/* Initialise the device on an already-open bus: power on, reset the data
42	 * register, start continuous high-res mode, then wait one worst-case
43	 * conversion so the first read returns real data. The power-on write is the
44	 * first point where a missing device shows up (no ACK -> GT_ERR_IO).
45	 * Takes ownership of `bus`: on any failure the bus is closed and NULL is
46	 * returned, so the caller never has to clean up. */
47	gt_light_sensor *gt_light_open_bus(gt_i2c_bus bus)
48	{
49	    if (bus.ops == NULL) {
50	        return NULL;
51	    }
52	
53	    gt_light_sensor *s = malloc(sizeof *s);
54	    if (s == NULL) {
55	        bus.ops->close(bus.ctx);
56	        return NULL;
57	    }
58	    s->bus = bus;
59	
60	    if (send_cmd(s, GT_BH1750_POWER_ON) != GT_OK ||
61	        send_cmd(s, GT_BH1750_RESET) != GT_OK ||
62	        send_cmd(s, GT_BH1750_CONT_HRES) != GT_OK) {
63	        bus.ops->close(bus.ctx);
64	        free(s);
65	        return NULL;
66	    }
67	
68	    bus.ops->sleep_ms(bus.ctx, GT_BH1750_MEAS_MAX_MS);
69	    return s;
70	}
71	
72	/* Read the latest measurement as a raw 16-bit count into `raw_out`.
73	 * A failed read is retried up to GT_LIGHT_RETRIES times, GT_LIGHT_RETRY_GAP_MS
74	 * apart; if every attempt fails, returns GT_ERR_IO and leaves `raw_out`
75	 * untouched so the caller can skip the sample. GT_ERR_INVAL on NULL args. */
76	gt_status gt_light_read(gt_light_sensor *s, uint32_t *raw_out)
77	{
78	    if (s == NULL || raw_out == NULL) {
79	        return GT_ERR_INVAL;
80	    }
81	
82	    uint8_t b[2];
83	    for (int attempt = 0; attempt <= GT_LIGHT_RETRIES; attempt++) {
84	        if (attempt > 0) {
85	            s->bus.ops->sleep_ms(s->bus.ctx, GT_LIGHT_RETRY_GAP_MS);
86	        }
87	        if (s->bus.ops->read(s->bus.ctx, b, sizeof b) == GT_OK) {
88	            *raw_out = ((uint32_t)b[0] << 8) | b[1];
89	            return GT_OK;
90	        }
91	    }
92	    return GT_ERR_IO;
93	}
94	
95	/* Power the device down (best effort: an unplugged sensor must still close
96	 * cleanly), then release the bus and the driver state. NULL-safe. */
97	void gt_light_close(gt_light_sensor *s)
98	{
99	    if (s == NULL) {
100	        return;
101	    }
102	    (void)send_cmd(s, GT_BH1750_POWER_DOWN);
103	    s->bus.ops->close(s->bus.ctx);
104	    free(s);
105	}
