1	/* Linux /dev/i2c-N implementation of the gt_i2c_ops seam (see i2c_bus.h).
2	 *
3	 * Purpose: this file is the only place that makes I2C system calls. It moves
4	 * raw bytes between the Pi and one device address and knows nothing about any
5	 * particular sensor; protocol logic (BH1750 commands, decoding, retry policy)
6	 * lives in the drivers (light_sensor.c, soil_sensor.c).
7	 *
8	 * Why it matters: drivers call only bus.ops->read/write/sleep_ms/close, so
9	 * tests can substitute a fake bus and exercise every driver path, including
10	 * injected I/O failures, in WSL/CI with no /dev/i2c-1. On the Pi, this file
11	 * is the real path to the hardware.
12	 *
13	 * Linux model: the kernel's i2c-bcm2835 driver exposes the bus as
14	 * /dev/i2c-1. open() it, ioctl(I2C_SLAVE, addr) to pick the device, then
15	 * each write()/read() is one complete I2C transaction (START .. STOP).
16	 * A device that does not ACK makes the call fail with -1 (EIO/ENXIO). */
17	#include "i2c_bus.h"
18	
19	#include <errno.h>
20	#include <fcntl.h>
21	#include <stdlib.h>
22	#include <sys/ioctl.h>
23	#include <time.h>
24	#include <unistd.h>
25	#include <linux/i2c-dev.h>
26	
27	/* Per-bus state, passed to every op as the opaque `ctx`. Each opened sensor
28	 * gets its own fd bound to its own address; the ops table is shared. */
29	typedef struct {
30	    int fd;
31	} linux_i2c;
32	
33	/* Send `len` bytes to the device in one I2C write transaction.
34	 * Used by drivers for commands (e.g. BH1750 power-on / mode select).
35	 * Retries only on EINTR (a signal interrupted the call before any transfer);
36	 * any real bus error or partial transfer is GT_ERR_IO and the driver decides
37	 * whether to retry. */
38	static gt_status linux_write(void *ctx, const uint8_t *buf, size_t len)
39	{
40	    linux_i2c *b = ctx;
41	    ssize_t n;
42	    do {
43	        n = write(b->fd, buf, len);
44	    } while (n < 0 && errno == EINTR);
45	    /* A short write means the device NACKed partway: treat as failure. */
46	    return (n == (ssize_t)len) ? GT_OK : GT_ERR_IO;
47	}
48	
49	/* Read exactly `len` bytes from the device in one I2C read transaction.
50	 * Used by drivers to fetch measurements (BH1750: 2 bytes, high byte first).
51	 * Same EINTR handling as linux_write; a short read is GT_ERR_IO. Decoding
52	 * and retry policy stay in the driver. */
53	static gt_status linux_read(void *ctx, uint8_t *buf, size_t len)
54	{
55	    linux_i2c *b = ctx;
56	    ssize_t n;
57	    do {
58	        n = read(b->fd, buf, len);
59	    } while (n < 0 && errno == EINTR);
60	    return (n == (ssize_t)len) ? GT_OK : GT_ERR_IO;
61	}
62	
63	/* Block for `ms` milliseconds. Drivers wait through the bus (BH1750 settle
64	 * after mode select, gap between read retries) so a test fake can record the
65	 * wait instead of sleeping. nanosleep is used because usleep is not declared
66	 * under _POSIX_C_SOURCE=200809L; on EINTR it resumes with the time left. */
67	static void linux_sleep_ms(void *ctx, uint32_t ms)
68	{
69	    (void)ctx;
70	    struct timespec req = { .tv_sec = ms / 1000, .tv_nsec = (long)(ms % 1000) * 1000000L };
71	    /* Resume with the remaining time if a signal interrupts the sleep. */
72	    while (nanosleep(&req, &req) < 0 && errno == EINTR) {
73	    }
74	}
75	
76	/* Release the bus: close the fd and free the per-bus state. Called by the
77	 * driver's close, or by its open if device initialisation fails. NULL-safe. */
78	static void linux_close(void *ctx)
79	{
80	    linux_i2c *b = ctx;
81	    if (b == NULL) {
82	        return;
83	    }
84	    close(b->fd);
85	    free(b);
86	}
87	
88	/* The real implementation of the seam. The functions above are static, so
89	 * the rest of the program can reach them only through this table. */
90	static const gt_i2c_ops linux_ops = {
91	    .write    = linux_write,
92	    .read     = linux_read,
93	    .sleep_ms = linux_sleep_ms,
94	    .close    = linux_close,
95	};
96	
97	/* Open the I2C bus at `dev` (e.g. "/dev/i2c-1") and bind it to the 7-bit
98	 * device address `addr` (0x23 for the BH1750). On success fills `out` with
99	 * the Linux ops and a new context; the caller owns it and must call
100	 * out->ops->close(out->ctx). Note this does not prove the device is present:
101	 * ioctl(I2C_SLAVE) succeeds for an empty address, and the first missing ACK
102	 * shows up on the first read/write.
103	 * Returns GT_ERR_INVAL (NULL args), GT_ERR_NOMEM, or GT_ERR_IO (cannot open
104	 * dev, e.g. I2C disabled or no permission, or address rejected). Every
105	 * failure path undoes what it already did, so nothing leaks. */
106	gt_status gt_i2c_linux_open(const char *dev, uint8_t addr, gt_i2c_bus *out)
107	{
108	    if (dev == NULL || out == NULL) {
109	        return GT_ERR_INVAL;
110	    }
111	
112	    linux_i2c *b = malloc(sizeof *b);
113	    if (b == NULL) {
114	        return GT_ERR_NOMEM;
115	    }
116	
117	    b->fd = open(dev, O_RDWR);
118	    if (b->fd < 0) {
119	        free(b);
120	        return GT_ERR_IO;
121	    }
122	
123	    /* Bind this fd to one 7-bit slave address; later read/write go to it. */
124	    if (ioctl(b->fd, I2C_SLAVE, (unsigned long)addr) < 0) {
125	        close(b->fd);
126	        free(b);
127	        return GT_ERR_IO;
128	    }
129	
130	    out->ops = &linux_ops;
131	    out->ctx = b;
132	    return GT_OK;
133	}
