1	#ifndef CHECK_H
2	#define CHECK_H
3	
4	/* Minimal test checks. Each failing check prints file:line and is counted;
5	 * tests keep running so one run reports every failure. A test file lists
6	 * its cases in a test_case_t table and its main() is
7	 * `return RUN_TESTS(tests);`, which prints [ID] name PASS/FAIL per case
8	 * and gives make test / CI a nonzero exit if any case failed. */
9	#include <stddef.h>
