7	
8	/* Hardware seam: drivers talk to the bus only through these ops, so tests
9	 * can swap in a fake device instead of /dev/i2c-1. */
10	typedef struct {
11	    gt_status (*write)(void *ctx, const uint8_t *buf, size_t len);
12	    gt_status (*read)(void *ctx, uint8_t *buf, size_t len);   /* short read => GT_ERR_IO */
13	    void      (*sleep_ms)(void *ctx, uint32_t ms);             /* injectable so tests don't sleep */
14	    void      (*close)(void *ctx);
15	} gt_i2c_ops;
16	
17	typedef struct {
18	    const gt_i2c_ops *ops;
19	    void             *ctx;
20	} gt_i2c_bus;
21	
22	/* Linux impl: open(dev, O_RDWR) + ioctl(I2C_SLAVE, addr). dev: e.g. "/dev/i2c-1" */
23	gt_status gt_i2c_linux_open(const char *dev, uint8_t addr, gt_i2c_bus *out);
24	
