1	/* Linux /dev/i2c-N implementation of the gt_i2c_ops seam (see i2c_bus.h).
2	 *
3	 * Purpose: this file is the only place that makes I2C system calls. It moves
4	 * raw bytes between the Pi and one device address and knows nothing about any
5	 * particular sensor; protocol logic (BH1750 commands, decoding, retry policy)
6	 * lives in the drivers (light_sensor.c, soil_sensor.c).
7	 *
8	 * Why it matters: drivers call only bus.ops->read/write/sleep_ms/close, so
9	 * tests can substitute a fake bus and exercise every driver path, including
10	 * injected I/O failures, in WSL/CI with no /dev/i2c-1. On the Pi, this file
11	 * is the real path to the hardware.
12	 *
13	 * Linux model: the kernel's i2c-bcm2835 driver exposes the bus as
14	 * /dev/i2c-1. open() it, ioctl(I2C_SLAVE, addr) to pick the device, then
15	 * each write()/read() is one complete I2C transaction (START .. STOP).
16	 * A device that does not ACK makes the call fail with -1 (EIO/ENXIO). */
17	#include "i2c_bus.h"
18	
19	#include <errno.h>
20	#include <fcntl.h>
21	#include <stdlib.h>
22	#include <sys/ioctl.h>
23	#include <time.h>
24	#include <unistd.h>
25	#include <linux/i2c-dev.h>
26	
27	/* Per-bus state, passed to every op as the opaque `ctx`. Each opened sensor
28	 * gets its own fd bound to its own address; the ops table is shared. */
29	typedef struct {
30	    int fd;
31	} linux_i2c;
32	
33	/* Send `len` bytes to the device in one I2C write transaction.
34	 * Used by drivers for commands (e.g. BH1750 power-on / mode select).
35	 * Retries only on EINTR (a signal interrupted the call before any transfer);
36	 * any real bus error or partial transfer is GT_ERR_IO and the driver decides
37	 * whether to retry. */
38	static gt_status linux_write(void *ctx, const uint8_t *buf, size_t len)
39	{
40	    linux_i2c *b = ctx;
41	    ssize_t n;
42	    do {
43	        n = write(b->fd, buf, len);
44	    } while (n < 0 && errno == EINTR);
45	    /* A short write means the device NACKed partway: treat as failure. */
46	    return (n == (ssize_t)len) ? GT_OK : GT_ERR_IO;
47	}
48	
49	/* Read exactly `len` bytes from the device in one I2C read transaction.
50	 * Used by drivers to fetch measurements (BH1750: 2 bytes, high byte first).
51	 * Same EINTR handling as linux_write; a short read is GT_ERR_IO. Decoding
52	 * and retry policy stay in the driver. */
53	static gt_status linux_read(void *ctx, uint8_t *buf, size_t len)
54	{
55	    linux_i2c *b = ctx;
56	    ssize_t n;
57	    do {
58	        n = read(b->fd, buf, len);
59	    } while (n < 0 && errno == EINTR);
60	    return (n == (ssize_t)len) ? GT_OK : GT_ERR_IO;
61	}
62	
63	/* Block for `ms` milliseconds. Drivers wait through the bus (BH1750 settle
64	 * after mode select, gap between read retries) so a test fake can record the
65	 * wait instead of sleeping. nanosleep is used because usleep is not declared
66	 * under _POSIX_C_SOURCE=200809L; on EINTR it resumes with the time left. */
67	static void linux_sleep_ms(void *ctx, uint32_t ms)
68	{
69	    (void)ctx;
70	    struct timespec req = { .tv_sec = ms / 1000, .tv_nsec = (long)(ms % 1000) * 1000000L };
71	    /* Resume with the remaining time if a signal interrupts the sleep. */
72	    while (nanosleep(&req, &req) < 0 && errno == EINTR) {
73	    }
74	}
75	
76	/* Release the bus: close the fd and free the per-bus state. Called by the
77	 * driver's close, or by its open if device initialisation fails. NULL-safe. */
78	static void linux_close(void *ctx)
79	{
80	    linux_i2c *b = ctx;
81	    if (b == NULL) {
82	        return;
83	    }
84	    close(b->fd);
85	    free(b);
86	}
87	
88	/* The real implementation of the seam. The functions above are static, so
89	 * the rest of the program can reach them only through this table. */
90	static const gt_i2c_ops linux_ops = {
91	    .write    = linux_write,
92	    .read     = linux_read,
93	    .sleep_ms = linux_sleep_ms,
94	    .close    = linux_close,
95	};
96	
97	/* Open the I2C bus at `dev` (e.g. "/dev/i2c-1") and bind it to the 7-bit
98	 * device address `addr` (0x23 for the BH1750). On success fills `out` with
99	 * the Linux ops and a new context; the caller owns it and must call
100	 * out->ops->close(out->ctx). Note this does not prove the device is present:
101	 * ioctl(I2C_SLAVE) succeeds for an empty address, and the first missing ACK
102	 * shows up on the first read/write.
103	 * Returns GT_ERR_INVAL (NULL args), GT_ERR_NOMEM, or GT_ERR_IO (cannot open
104	 * dev, e.g. I2C disabled or no permission, or address rejected). Every
105	 * failure path undoes what it already did, so nothing leaks. */
106	gt_status gt_i2c_linux_open(const char *dev, uint8_t addr, gt_i2c_bus *out)
107	{
108	    if (dev == NULL || out == NULL) {
109	        return GT_ERR_INVAL;
110	    }
111	
112	    linux_i2c *b = malloc(sizeof *b);
113	    if (b == NULL) {
114	        return GT_ERR_NOMEM;
115	    }
116	
117	    b->fd = open(dev, O_RDWR);
118	    if (b->fd < 0) {
119	        free(b);
120	        return GT_ERR_IO;
121	    }
122	
123	    /* Bind this fd to one 7-bit slave address; later read/write go to it. */
124	    if (ioctl(b->fd, I2C_SLAVE, (unsigned long)addr) < 0) {
125	        close(b->fd);
126	        free(b);
127	        return GT_ERR_IO;
128	    }
129	
130	    out->ops = &linux_ops;
131	    out->ctx = b;
132	    return GT_OK;
133	}
134

1	/* Unit tests for reading the BH1750 driver (src/light_sensor.c) against a
2	 * fake bus: gt_light_read and gt_light_raw_to_lux.
3	 *
4	 * Purpose: prove decoding and lux conversion, that reads send no commands,
5	 * the read retry policy and its timing budget, and that bad reads and bad
6	 * arguments never produce a value. Run under make test / asan / memcheck.
7	 * Implements LSR-01 through LSR-10. Opening is in test_light_open.c,
8	 * closing in test_light_close.c.
9	 *
10	 * What these tests cannot prove: that sampling runs at 1 Hz. That belongs
11	 * to the sampler, which schedules the reads this driver only performs. */
12	#include <stdint.h>
13	
14	#include "check.h"
15	#include "fake_i2c.h"
16	#include "light_sensor.h"
17	
18	/* Marker for "the driver must not have written to raw_out". */
19	#define UNTOUCHED 0xDEADBEEFu
20	
21	/* Reset `f` and open a sensor on it; the init traffic is left in `f`. */
22	static gt_light_sensor *open_on(fake_i2c *f)
23	{
24	    return gt_light_open_bus(fake_i2c_bus(f));
25	}
26	
27	static int near(double a, double b)
28	{
29	    double d = a - b;
30	    return d < 0.01 && d > -0.01;
31	}
32	
33	/* ---- LSR-01: data decodes big-endian ----
34	 * Data arrives high byte first: 0x01 0x2C = 300. */
35	static void test_lsr01_read_decodes_big_endian(void)
36	{
37	    fake_i2c f;
38	    gt_light_sensor *s = open_on(&f);
39	    const uint8_t data[] = { 0x01, 0x2C };
40	    fake_i2c_push_read(&f, data, sizeof data);
41	
42	    uint32_t raw = UNTOUCHED;
43	    CHECK_EQ(gt_light_read(s, &raw), GT_OK);
44	    CHECK_EQ(raw, 300);
45	
46	    gt_light_close(s);
47	}
48	
49	/* ---- LSR-02: full 16-bit range decodes ----
50	 * 0 (dark) and 65535 (saturated). */
51	static void test_lsr02_read_range_limits(void)
52	{
53	    fake_i2c f;
54	    gt_light_sensor *s = open_on(&f);
55	    const uint8_t data[] = { 0x00, 0x00, 0xFF, 0xFF };
56	    fake_i2c_push_read(&f, data, sizeof data);
57	
58	    uint32_t raw = UNTOUCHED;
59	    CHECK_EQ(gt_light_read(s, &raw), GT_OK);
60	    CHECK_EQ(raw, 0);
61	    CHECK_EQ(gt_light_read(s, &raw), GT_OK);
62	    CHECK_EQ(raw, 65535);
63	
64	    gt_light_close(s);
65	}
66	
67	/* ---- LSR-03: back-to-back reads return measurements in order ---- */
68	static void test_lsr03_reads_in_order(void)
69	{
70	    fake_i2c f;
71	    gt_light_sensor *s = open_on(&f);
72	    const uint8_t data[] = { 0x01, 0x2C, 0x00, 0x00, 0x00, 0x78 };
73	    fake_i2c_push_read(&f, data, sizeof data);
74	
75	    uint32_t raw = UNTOUCHED;
76	    CHECK_EQ(gt_light_read(s, &raw), GT_OK);
77	    CHECK_EQ(raw, 300);
78	    CHECK_EQ(gt_light_read(s, &raw), GT_OK);
79	    CHECK_EQ(raw, 0);
80	    CHECK_EQ(gt_light_read(s, &raw), GT_OK);
81	    CHECK_EQ(raw, 120);
82	
83	    gt_light_close(s);
84	}
85	
86	/* ---- LSR-04: reads send no commands ----
87	 * In continuous mode reads are pure reads: re-sending a mode command would
88	 * restart the conversion and the next read would return stale data. */
89	static void test_lsr04_reads_send_no_commands(void)
90	{
91	    fake_i2c f;
92	    gt_light_sensor *s = open_on(&f);
93	    const uint8_t data[] = { 0x00, 0x10, 0x00, 0x20, 0x00, 0x30 };
94	    fake_i2c_push_read(&f, data, sizeof data);
95	    int writes_after_open = f.write_calls;
96	
97	    uint32_t raw;
98	    for (int i = 0; i < 3; i++) {
99	        CHECK_EQ(gt_light_read(s, &raw), GT_OK);
100	    }
101	    CHECK_EQ(f.write_calls, writes_after_open);
102	
103	    gt_light_close(s);
104	}
105	
106	/* ---- LSR-05: lux = count / 1.2 ----
107	 * High-res mode conversion (datasheet). */
108	static void test_lsr05_lux_conversion(void)
109	{
110	    CHECK(near(gt_light_raw_to_lux(0), 0.0));
111	    CHECK(near(gt_light_raw_to_lux(120), 100.0));
112	    CHECK(near(gt_light_raw_to_lux(65535), 54612.5));
113	}
114	
115	/* ---- LSR-06: a transient failure is retried and recovers ----
116	 * Retried after a 10 ms gap and the read succeeds. */
117	static void test_lsr06_read_retry_recovers(void)
118	{
119	    fake_i2c f;
120	    gt_light_sensor *s = open_on(&f);
121	    const uint8_t data[] = { 0x01, 0x2C };
122	    fake_i2c_push_read(&f, data, sizeof data);
123	    int sleeps_after_open = f.sleep_calls;
124	    uint32_t slept_after_open = f.slept_ms_total;
125	    f.fail_reads = 2;
126	
127	    uint32_t raw = UNTOUCHED;
128	    CHECK_EQ(gt_light_read(s, &raw), GT_OK);
129	    CHECK_EQ(raw, 300);
130	    CHECK_EQ(f.read_calls, 3);
131	    CHECK_EQ(f.sleep_calls - sleeps_after_open, 2);
132	    CHECK_EQ(f.slept_ms_total - slept_after_open, 2 * GT_LIGHT_RETRY_GAP_MS);
133	
134	    gt_light_close(s);
135	}
136	
137	/* ---- LSR-07: retries exhausted returns GT_ERR_IO within budget ----
138	 * Every attempt fails: 1 try + 3 retries, 3 gaps, then GT_ERR_IO with
139	 * raw_out untouched so the caller skips the sample instead of storing junk.
140	 * Also the timing budget: even this worst case waits only 30 ms, well
141	 * inside the 1 s light period, so retries cannot make sampling miss a slot. */
142	static void test_lsr07_read_retry_exhausted(void)
143	{
144	    fake_i2c f;
145	    gt_light_sensor *s = open_on(&f);
146	    int sleeps_after_open = f.sleep_calls;
147	    uint32_t slept_after_open = f.slept_ms_total;
148	    f.fail_reads = 1 + GT_LIGHT_RETRIES;
149	
150	    uint32_t raw = UNTOUCHED;
151	    CHECK_EQ(gt_light_read(s, &raw), GT_ERR_IO);
152	    CHECK_EQ(raw, UNTOUCHED);
153	    CHECK_EQ(f.read_calls, 1 + GT_LIGHT_RETRIES);
154	    CHECK_EQ(f.sleep_calls - sleeps_after_open, GT_LIGHT_RETRIES);
155	
156	    uint32_t waited = f.slept_ms_total - slept_after_open;
157	    CHECK_EQ(waited, GT_LIGHT_RETRIES * GT_LIGHT_RETRY_GAP_MS);
158	    CHECK(waited < 1000);
159	
160	    gt_light_close(s);
161	}
162	
163	/* ---- LSR-08: a short read is an error ----
164	 * The device stopped after 1 byte: a failure, not a value. */
165	static void test_lsr08_read_short_is_error(void)
166	{
167	    fake_i2c f;
168	    gt_light_sensor *s = open_on(&f);
169	    const uint8_t half[] = { 0x01 };
170	    fake_i2c_push_read(&f, half, sizeof half);
171	
172	    uint32_t raw = UNTOUCHED;
173	    CHECK_EQ(gt_light_read(s, &raw), GT_ERR_IO);
174	    CHECK_EQ(raw, UNTOUCHED);
175	
176	    gt_light_close(s);
177	}
178	
179	/* ---- LSR-09: the handle works again after an outage ----
180	 * After a read gives up (sensor briefly unplugged), the same handle works
181	 * again once the device answers; no reopen is needed. */
182	static void test_lsr09_read_works_after_outage(void)
183	{
184	    fake_i2c f;
185	    gt_light_sensor *s = open_on(&f);
186	    f.fail_reads = 1 + GT_LIGHT_RETRIES;
187	
188	    uint32_t raw = UNTOUCHED;
189	    CHECK_EQ(gt_light_read(s, &raw), GT_ERR_IO);
190	
191	    const uint8_t data[] = { 0x00, 0x78 };
192	    fake_i2c_push_read(&f, data, sizeof data);
193	    CHECK_EQ(gt_light_read(s, &raw), GT_OK);
194	    CHECK_EQ(raw, 120);
195	
196	    gt_light_close(s);
197	}
198	
199	/* ---- LSR-10: NULL arguments are rejected ----
200	 * Rejected without touching the bus. */
201	static void test_lsr10_null_args(void)
202	{
203	    fake_i2c f;
204	    gt_light_sensor *s = open_on(&f);
205	    uint32_t raw = UNTOUCHED;
206	
207	    CHECK_EQ(gt_light_read(NULL, &raw), GT_ERR_INVAL);
208	    CHECK_EQ(gt_light_read(s, NULL), GT_ERR_INVAL);
209	    CHECK_EQ(f.read_calls, 0);
210	    CHECK_EQ(raw, UNTOUCHED);
211	
212	    gt_light_close(s);
213	    gt_light_close(NULL);
214	}
215	
216	static const test_case_t tests[] = {
217	    {"LSR-01", "data decodes big-endian", test_lsr01_read_decodes_big_endian},
218	    {"LSR-02", "full 16-bit range decodes", test_lsr02_read_range_limits},
219	    {"LSR-03", "back-to-back reads return in order", test_lsr03_reads_in_order},
220	    {"LSR-04", "reads send no commands", test_lsr04_reads_send_no_commands},
221	    {"LSR-05", "lux = count / 1.2", test_lsr05_lux_conversion},
222	    {"LSR-06", "transient failure is retried and recovers", test_lsr06_read_retry_recovers},
223	    {"LSR-07", "exhausted retries give GT_ERR_IO in budget", test_lsr07_read_retry_exhausted},
224	    {"LSR-08", "a short read is an error", test_lsr08_read_short_is_error},
225	    {"LSR-09", "handle works again after an outage", test_lsr09_read_works_after_outage},
226	    {"LSR-10", "NULL arguments are rejected", test_lsr10_null_args},
227	};
228	
229	int main(void)
230	{
231	    return RUN_TESTS(tests);
232	}
