1	/* Unit tests for opening the BH1750 driver (src/light_sensor.c) against a
2	 * fake bus: gt_light_open / gt_light_open_bus.
3	 *
4	 * Purpose: prove the driver detects a missing or broken device and leaves
5	 * nothing open when it gives up, and that a successful open sends the init
6	 * command sequence and waits for the first conversion. Run under
7	 * make test / asan / memcheck, so leaks and double-closes also fail.
8	 * Implements LSO-01 through LSO-06. Reading is in test_light_read.c,
9	 * closing in test_light_close.c.
10	 *
11	 * What these tests cannot prove: that a real chip sits at 0x23 on the wire.
12	 * That needs the Pi (i2cdetect / the light_probe tool). */
13	#include "check.h"
14	#include "fake_i2c.h"
15	#include "light_sensor.h"
16	
17	/* Reset `f` and open a sensor on it; the init traffic is left in `f`. */
18	static gt_light_sensor *open_on(fake_i2c *f)
19	{
20	    return gt_light_open_bus(fake_i2c_bus(f));
21	}
22	
23	/* ---- LSO-01: I2C address is 0x23 ----
24	 * The address is fixed by the ADDR pin wiring (low/floating = 0x23); pin it
25	 * so a typo can't silently point the driver at another device. */
26	static void test_lso01_address_is_0x23(void)
27	{
28	    CHECK_EQ(GT_LIGHT_I2C_ADDR, 0x23);
29	}
30	
31	/* ---- LSO-02: open without a bus device fails ----
32	 * No bus device at all (I2C disabled, wrong path): this runs the real
33	 * gt_i2c_linux_open, whose open() fails, so open must return NULL. */
34	static void test_lso02_open_without_bus_device_fails(void)
35	{
36	    CHECK(gt_light_open("/nonexistent/i2c-1") == NULL);
37	    CHECK(gt_light_open(NULL) == NULL);
38	}
39	
40	/* ---- LSO-03: open fails when the device is missing ----
41	 * Nothing answers at the address: the first write (POWER_ON) is NACKed.
42	 * Open must fail, close the bus it was given exactly once, and not wait. */
43	static void test_lso03_open_missing_device_fails(void)
44	{
45	    fake_i2c f;
46	    gt_i2c_bus bus = fake_i2c_bus(&f);
47	    f.fail_writes = 1;
48	
49	    CHECK(gt_light_open_bus(bus) == NULL);
50	    CHECK_EQ(f.write_calls, 1);
51	    CHECK_EQ(f.closed, 1);
52	    CHECK_EQ(f.sleep_calls, 0);
53	}
54	
55	/* ---- LSO-04: open fails cleanly at each init command ----
56	 * The device ACKs some init commands, then NACKs one (e.g. a loose wire).
57	 * For each of the 3 commands: open stops at the failed one, sends nothing
58	 * after it, never waits, and closes the bus exactly once. */
59	static void test_lso04_open_fails_at_each_init_command(void)
60	{
61	    for (int k = 1; k <= 3; k++) {
62	        fake_i2c f;
63	        gt_i2c_bus bus = fake_i2c_bus(&f);
64	        f.fail_write_at = k;
65	
66	        CHECK(gt_light_open_bus(bus) == NULL);
67	        CHECK_EQ(f.write_calls, k);
68	        CHECK_EQ(f.closed, 1);
69	        CHECK_EQ(f.sleep_calls, 0);
70	    }
71	}
72	
73	/* ---- LSO-05: a bus with no ops table is rejected ----
74	 * Rejected rather than dereferenced. */
75	static void test_lso05_open_null_ops_fails(void)
76	{
77	    gt_i2c_bus bus = { .ops = NULL, .ctx = NULL };
78	    CHECK(gt_light_open_bus(bus) == NULL);
79	}
80	
81	/* ---- LSO-06: open sends the init sequence ----
82	 * Open sends POWER_ON, RESET, CONT_HRES, one byte each in that order, then
83	 * waits one worst-case conversion so the first read is real data. */
84	static void test_lso06_open_sends_init_sequence(void)
85	{
86	    fake_i2c f;
87	    gt_light_sensor *s = open_on(&f);
88	
89	    CHECK(s != NULL);
90	    CHECK_EQ(f.write_calls, 3);
91	    CHECK_EQ(f.n_written, 3);
92	    CHECK_EQ(f.written[0], GT_BH1750_POWER_ON);
93	    CHECK_EQ(f.written[1], GT_BH1750_RESET);
94	    CHECK_EQ(f.written[2], GT_BH1750_CONT_HRES);
95	    CHECK_EQ(f.sleep_calls, 1);
96	    CHECK(f.slept_ms_total >= GT_BH1750_MEAS_MAX_MS);
97	    CHECK_EQ(f.closed, 0);
98	
99	    gt_light_close(s);
100	}
101	
102	static const test_case_t tests[] = {
103	    {"LSO-01", "I2C address is 0x23", test_lso01_address_is_0x23},
104	    {"LSO-02", "open without a bus device fails", test_lso02_open_without_bus_device_fails},
105	    {"LSO-03", "open fails when the device is missing", test_lso03_open_missing_device_fails},
106	    {"LSO-04", "open fails cleanly at each init command",
107	     test_lso04_open_fails_at_each_init_command},
108	    {"LSO-05", "a bus with no ops table is rejected", test_lso05_open_null_ops_fails},
109	    {"LSO-06", "open sends the init sequence", test_lso06_open_sends_init_sequence},
110	};
111	
112	int main(void)
113	{
114	    return RUN_TESTS(tests);
115	}
