1	#ifndef CHECK_H
2	#define CHECK_H
3	
4	/* Minimal test checks. Each failing check prints file:line and is counted;
5	 * tests keep running so one run reports every failure. A test file lists
6	 * its cases in a test_case_t table and its main() is
7	 * `return RUN_TESTS(tests);`, which prints [ID] name PASS/FAIL per case
8	 * and gives make test / CI a nonzero exit if any case failed. */
9	#include <stddef.h>
10	#include <stdio.h>
11	
12	static int check_failures;
13	
14	#define CHECK(cond)                                                     \
15	    do {                                                                \
16	        if (!(cond)) {                                                  \
17	            fprintf(stderr, "    %s:%d: CHECK failed: %s\n",            \
18	                    __FILE__, __LINE__, #cond);                         \
19	            check_failures++;                                           \
20	        }                                                               \
21	    } while (0)
22	
23	/* Integer equality; prints both values on failure. */
24	#define CHECK_EQ(a, b)                                                  \
25	    do {                                                                \
26	        long long check_a_ = (long long)(a);                            \
27	        long long check_b_ = (long long)(b);                            \
28	        if (check_a_ != check_b_) {                                     \
29	            fprintf(stderr, "    %s:%d: CHECK_EQ failed: %s == %s "     \
30	                    "(%lld vs %lld)\n", __FILE__, __LINE__, #a, #b,     \
31	                    check_a_, check_b_);                                \
32	            check_failures++;                                           \
33	        }                                                               \
34	    } while (0)
35	
36	/* One case: an ID like "LSO-03", a short name, and a void test body. */
37	typedef struct {
38	    const char *id;
39	    const char *name;
40	    void (*run)(void);
41	} test_case_t;
42	
43	/* Run every case in order. A case passes if it added no failures; the
44	 * count is snapshotted, never reset, so a later failure cannot flip an
45	 * earlier verdict. Flushing keeps a case's diagnostics above its line.
46	 * inline so files not yet using it don't trip -Wunused-function. */
47	static inline int run_tests(const test_case_t *t, size_t n)
48	{
49	    size_t passed = 0;
50	    for (size_t i = 0; i < n; i++) {
51	        int before = check_failures;
52	        t[i].run();
53	        int ok = (check_failures == before);
54	        fflush(stderr);
55	        printf("[%s] %-45s %s\n", t[i].id, t[i].name, ok ? "PASS" : "FAIL");
56	        fflush(stdout);
57	        if (ok) {
58	            passed++;
59	        }
60	    }
61	    printf("%zu/%zu tests passed\n", passed, n);
62	    return passed == n ? 0 : 1;
63	}
64	
65	#define RUN_TESTS(tbl) run_tests((tbl), sizeof(tbl) / sizeof((tbl)[0]))
66	
67	#endif
68

1	#ifndef FAKE_I2C_H
2	#define FAKE_I2C_H
3	
4	/* Fake gt_i2c_ops for driver tests: no /dev/i2c-1, no real sleeping.
5	 *
6	 * A test declares a fake_i2c on the stack, scripts read data and failures,
7	 * passes fake_i2c_bus(&f) to the driver, then inspects what the driver did:
8	 * bytes written, read attempts, waits and closes. The fake is the bus ctx
9	 * and is owned by the test, so close() only counts and never frees.
10	 * fake_i2c_bus() zeroes the fake, so call it before scripting anything.
11	 *
12	 * Header-only (static inline) because the Makefile links each test .c with
13	 * src/ only; inline keeps unused helpers from tripping -Werror. */
14	#include <stddef.h>
15	#include <stdint.h>
16	#include <string.h>
17	
18	#include "i2c_bus.h"
19	
20	#define FAKE_I2C_MAX_WRITTEN 64
21	#define FAKE_I2C_MAX_READ    64
22	
23	typedef struct {
24	    /* Every attempted write, in order (failed ones too: the bus was driven). */
25	    uint8_t  written[FAKE_I2C_MAX_WRITTEN];
26	    size_t   n_written;
27	    int      write_calls;
28	
29	    /* Scripted read data, consumed front to back across read() calls. */
30	    uint8_t  read_data[FAKE_I2C_MAX_READ];
31	    size_t   n_read_data;
32	    size_t   read_pos;
33	    int      read_calls;
34	
35	    /* Failure injection: the next N calls of each kind return GT_ERR_IO. */
36	    int      fail_writes;
37	    int      fail_reads;
38	    /* Fail only the Nth write call (1-based, counted since fake_i2c_bus);
39	     * 0 = off. Lets a test pass the first commands and NACK a later one. */
40	    int      fail_write_at;
41	
42	    int      sleep_calls;
43	    uint32_t slept_ms_total;
44	    int      closed;
45	} fake_i2c;
46	
47	/* Append `len` bytes to the data later reads will return. */
48	static inline void fake_i2c_push_read(fake_i2c *f, const uint8_t *buf, size_t len)
49	{
50	    for (size_t i = 0; i < len && f->n_read_data < FAKE_I2C_MAX_READ; i++) {
51	        f->read_data[f->n_read_data++] = buf[i];
52	    }
53	}
54	
55	static inline gt_status fake_i2c_write(void *ctx, const uint8_t *buf, size_t len)
56	{
57	    fake_i2c *f = ctx;
58	    f->write_calls++;
59	    for (size_t i = 0; i < len && f->n_written < FAKE_I2C_MAX_WRITTEN; i++) {
60	        f->written[f->n_written++] = buf[i];
61	    }
62	    if (f->fail_writes > 0) {
63	        f->fail_writes--;
64	        return GT_ERR_IO;
65	    }
66	    if (f->fail_write_at == f->write_calls) {
67	        return GT_ERR_IO;
68	    }
69	    return GT_OK;
70	}
71	
72	/* A failed read consumes no data. Running out of scripted data is a short
73	 * read, which the real bus also reports as GT_ERR_IO. */
74	static inline gt_status fake_i2c_read(void *ctx, uint8_t *buf, size_t len)
75	{
76	    fake_i2c *f = ctx;
77	    f->read_calls++;
78	    if (f->fail_reads > 0) {
79	        f->fail_reads--;
80	        return GT_ERR_IO;
81	    }
82	    if (f->n_read_data - f->read_pos < len) {
83	        return GT_ERR_IO;
84	    }
85	    memcpy(buf, &f->read_data[f->read_pos], len);
86	    f->read_pos += len;
87	    return GT_OK;
88	}
89	
90	static inline void fake_i2c_sleep_ms(void *ctx, uint32_t ms)
91	{
92	    fake_i2c *f = ctx;
93	    f->sleep_calls++;
94	    f->slept_ms_total += ms;
95	}
96	
97	static inline void fake_i2c_close(void *ctx)
98	{
99	    fake_i2c *f = ctx;
100	    f->closed++;
101	}
102	
103	/* Reset `f` and return a bus that routes every op to it. */
104	static inline gt_i2c_bus fake_i2c_bus(fake_i2c *f)
105	{
106	    static const gt_i2c_ops ops = {
107	        .write    = fake_i2c_write,
108	        .read     = fake_i2c_read,
109	        .sleep_ms = fake_i2c_sleep_ms,
110	        .close    = fake_i2c_close,
111	    };
112	    memset(f, 0, sizeof *f);
113	    return (gt_i2c_bus){ .ops = &ops, .ctx = f };
114	}
115	
116	#endif
117

1	/* Unit tests for closing the BH1750 driver (src/light_sensor.c) against a
2	 * fake bus: gt_light_close.
3	 *
4	 * Purpose: prove close powers the chip down and releases the bus exactly
5	 * once, even when the chip no longer answers. Run under make test / asan /
6	 * memcheck, so leaks and double-closes also fail.
7	 * Implements LSC-01 and LSC-02. Opening is in test_light_open.c, reading
8	 * in test_light_read.c. */
9	#include "check.h"
10	#include "fake_i2c.h"
11	#include "light_sensor.h"
12	
13	/* Reset `f` and open a sensor on it; the init traffic is left in `f`. */
14	static gt_light_sensor *open_on(fake_i2c *f)
15	{
16	    return gt_light_open_bus(fake_i2c_bus(f));
17	}
18	
19	/* ---- LSC-01: close powers down and closes the bus ----
20	 * Power-down is the last command, and the bus is closed once. */
21	static void test_lsc01_close_powers_down(void)
22	{
23	    fake_i2c f;
24	    gt_light_sensor *s = open_on(&f);
25	
26	    gt_light_close(s);
27	    CHECK_EQ(f.n_written, 4);
28	    CHECK_EQ(f.written[3], GT_BH1750_POWER_DOWN);
29	    CHECK_EQ(f.closed, 1);
30	}
31	
32	/* ---- LSC-02: the bus is released when power-down fails ----
33	 * An unplugged sensor NACKs the power-down; the bus is still released. */
34	static void test_lsc02_close_when_power_down_fails(void)
35	{
36	    fake_i2c f;
37	    gt_light_sensor *s = open_on(&f);
38	    f.fail_writes = 1;
39	
40	    gt_light_close(s);
41	    CHECK_EQ(f.closed, 1);
42	}
43	
44	static const test_case_t tests[] = {
45	    {"LSC-01", "close powers down and closes the bus", test_lsc01_close_powers_down},
46	    {"LSC-02", "bus is released when power-down fails",
47	     test_lsc02_close_when_power_down_fails},
48	};
49	
50	int main(void)
51	{
52	    return RUN_TESTS(tests);
53	}
