/* Unit tests for naming sensor health transitions (src/sensor_health.c):
 * gt_health_event_name.
 *
 * Purpose: prove each transition maps to the exact event name in DESIGN.md's
 * failure-mode table (Sensor (I2C) row: sensor_offline, sensor_online), and
 * that "no transition" maps to nothing, so the caller logs only real
 * changes. Run under make test / asan / memcheck. Implements SHE-01 through
 * SHE-04. Producing the transitions is in test_health_record.c.
 *
 * What these tests cannot prove: that the light process actually logs the
 * name. That arrives with src/light_sensor_main.c. */
#include <string.h>

#include "check.h"
#include "sensor_health.h"

