    memset(untouched, 0x5A, sizeof untouched);

    for (size_t type_index = 0; type_index < sizeof unknown_types; type_index++) {
        gt_msg message = { .type = unknown_types[type_index], .sensor_id = GT_SENSOR_LIGHT,
